{"description":"Fetches yesterday's BTC open, close, and volume from CoinGecko.","id":"daily_btc","schedule":"0 8 * * *","steps":"- http_get: https://api.coingecko.com/api/v3/coins/bitcoin/market_chart?vs_currency=usd&days=2
- js_transform: |
    const { prices, total_volumes } = data;
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    yesterday.setHours(0,0,0,0);
    const startTs = yesterday.getTime();
    const endTs = startTs + 86400000;
    const openPrice = prices.find(p => p[0] >= startTs)?.[1] || prices[0][1];
    const closePrice = prices.find(p => p[0] <= endTs)?.[1] || prices[prices.length-1][1];
    const volume = total_volumes.find(v => v[0] >= startTs)?.[1] || total_volumes[0][1];
    return {
      date: yesterday.toISOString().split('T')[0],
      open: openPrice,
      close: closePrice,
      volume: volume
    };
- db_insert: btc_prices"}

