SQL SELECT close FROM btc_prices ORDER BY date DESC LIMIT 2 INTO rows;
# rows[0] = latest, rows[1] = previous
SET latest = rows[0].close;
SET previous = rows[1].close;
SET drop = (previous - latest) / previous;
IF drop > 0.05 THEN
  # Send Telegram message (replace TOKEN and CHAT_ID with real values)
  POST https://api.telegram.org/bot{{TOKEN}}/sendMessage
  BODY {"chat_id": "{{CHAT_ID}}", "text": "⚠️ Bitcoin price dropped >5% today (from {{previous}} EUR to {{latest}} EUR)."}
ENDIF"}

