calls.args:
{"description":"Fetch yesterday's BTC price from CoinGecko and write to btc_prices table.","id":"daily_btc","schedule":"0 8 * * *","steps":"fetch: {
  url: "https://api.coingecko.com/api/v3/coins/bitcoin/market_chart?vs_currency=usd&days=3&interval=daily"
}
transform: {
  // The API returns arrays of [timestamp, value]
  // prices[-1] is today, prices[-2] is yesterday, prices[-3] is day before
  // Yesterday's open is the price at the start of yesterday (prices[-3])
  // Yesterday's close is the price at the end of yesterday (prices[-2])
  // Volume is for the period ending at prices[-2]
  js: "
    const prices = data.prices;
    const volumes = data.total_volumes;
    const yesterday = prices[prices.length - 2];
    const dayBefore = prices[prices.length - 3];
    const volume = volumes[volumes.length - 2][1];

    return {
      date: new Date(yesterday[0]).toISOString().split('T')[0],
      open: dayBefore[1],
      close: yesterday[1],
      volume: volume
    };
  "
}
write: {
  table: "btc_prices"
}"}

